const item = $input.first();
const binary = item.binary ?? {};
const order = binary.order_workbook;
if (!order) throw new Error('Thiếu file đơn hàng');
if (!/\.(?:xls|xlsx|docx|pdf)$/i.test(String(order.fileName ?? ''))) throw new Error('File đơn hàng phải là .xls, .xlsx, .docx hoặc .pdf');
const sofKeys = Object.keys(binary).filter((key) => key === 'sof_workbook' || /^sof_workbook_\d+$/.test(key));
sofKeys.sort((a, b) => {
  if (a === 'sof_workbook') return -1;
  if (b === 'sof_workbook') return 1;
  return Number(a.split('_').pop()) - Number(b.split('_').pop());
});
if (sofKeys.length === 0) throw new Error('Cần tải lên ít nhất 1 file SOF');
if (sofKeys.length > 20) throw new Error('Chỉ được tải tối đa 20 file SOF mỗi lần');
const names = new Set();
for (const key of sofKeys) {
  const name = String(binary[key]?.fileName ?? '');
  if (!/\.(?:xls|xlsx|docx|pdf)$/i.test(name)) throw new Error(`SOF ${name || key} phải là .xls, .xlsx, .docx hoặc .pdf`);
  const normalized = name.toLocaleLowerCase();
  if (names.has(normalized)) throw new Error(`Trùng tên file SOF: ${name}`);
  names.add(normalized);
}
return [{json: {overwrite: false, sofBinaryFields: sofKeys.join(','), sofCount: sofKeys.length}, binary}];

const audit = $input.first().json;
if (audit.status === 'ERROR') throw new Error(audit.error || 'Hanger worker failed');
// A row DeepSeek resolved is MATCHED but was never checked against an approved
// rule, so counting only mismatch+review would let it reach the factory unseen.
const rows = Array.isArray(audit.row_results) ? audit.row_results : [];
const llmMatched = rows.filter((r) => r.status === 'MATCHED' && String(r.match_method || '').startsWith('LLM_')).length;
return [{json: {...audit, llm_matched: llmMatched, needsAttention: Number(audit.mismatch || 0) + Number(audit.review || 0) + llmMatched > 0}}];

return $input.all().map(({json}) => {
  const llm = json.llm?.enabled ? ` DeepSeek: ${json.llm.api_calls || 0} call, cache hit ${json.llm.cache?.hits ?? 0}.` : ' DeepSeek: tắt.';
  const scope = `Đã kiểm account: ${(json.accounts_checked || []).join(', ') || 'không có'}.`;
  const out = json.skipped_no_sof ? ` Bỏ qua ${json.skipped_no_sof} dòng của account chưa gửi SOF.` : '';
  const unverified = json.llm_matched ? ` Cần đối chiếu tay: ${json.llm_matched} dòng matched do DeepSeek suy ra, không theo luật đã duyệt.` : '';
  const src = json.order_source || {};
  const doc = (src.format === 'pdf' || src.format === 'docx')
    ? ` Đơn hàng ${src.format.toUpperCase()}: đọc ${src.extracted_rows} dòng, thiếu cột ${(src.fields_missing || []).join(', ') || 'không'}.`
    : '';
  return {json: {...json, status: 'COMPLETED_WITH_REVIEW',
    message: `${scope} Trong ${json.total_checked_rows} dòng: matched ${json.matched}, mismatch ${json.mismatch}, review ${json.review}.${unverified}${out}${doc}${llm}`}};
});

return $input.all().map(({json}) => {
  const llm = json.llm?.enabled ? ` DeepSeek: ${json.llm.api_calls || 0} call, cache hit ${json.llm.cache?.hits ?? 0}.` : ' DeepSeek: tắt.';
  const scope = `Đã kiểm account: ${(json.accounts_checked || []).join(', ') || 'không có'}.`;
  const out = json.skipped_no_sof ? ` Bỏ qua ${json.skipped_no_sof} dòng của account chưa gửi SOF.` : '';
  const src = json.order_source || {};
  const doc = (src.format === 'pdf' || src.format === 'docx')
    ? ` Đơn hàng ${src.format.toUpperCase()}: đọc ${src.extracted_rows} dòng, thiếu cột ${(src.fields_missing || []).join(', ') || 'không'}.`
    : '';
  return {json: {...json, status: 'COMPLETED',
    message: `${scope} ${json.matched}/${json.total_checked_rows} dòng matched.${out}${doc}${llm}`}};
});
